Q: Laravel API resourceCollection using array rather than model A: <pre class="lang-php prettyprint-override"><code>class ToDoAddapter
{
  public function asResource(bool $resource = true)
  {
    $this-&gt;resource = $resource;
    return $this;
  }

  public function getAllForUserId(...)
  {
    $data = Todo::BelongsUser($userId)
      -&gt;orderBy($sortField, $sortDir)
      -&gt;paginate($pageSize);

    if ($this-&gt;resource) {
      return new TodoCollection($data);
    }

    return $data-&gt;toArray();
  }
}
</code></pre>
<p>or another pattern</p>
<pre class="lang-php prettyprint-override"><code>class ToDoAddapter
{
  /**
  * @template T of object
  * @param class-string&lt;T&gt;|null $mapper
  * @returns array|T
  */
  public function getAllForUserId(..., ?string $mapper = null)
  {
    $data = Todo::BelongsUser($userId)
      -&gt;orderBy($sortField, $sortDir)
      -&gt;paginate($pageSize);

    if ($mapper) {
      return new $mapper($data);
    }

    return $data-&gt;toArray();
  }
}
</code></pre>
